"                document.addEventListener("DOMContentLoaded", () => {
                const table = document.getElementById("tbl_arbol");
                const data = [{"sys_pk":1,"parent":null,"codigo":"A","nombre":"Grupo A","importe":100},{"sys_pk":2,"parent":1,"codigo":"A1","nombre":"Subgrupo A1","importe":40},{"sys_pk":3,"parent":2,"codigo":"A1a","nombre":"Elemento A1a","importe":15},{"sys_pk":4,"parent":1,"codigo":"A2","nombre":"Subgrupo A2","importe":60},{"sys_pk":5,"parent":null,"codigo":"B","nombre":"Grupo B","importe":7},{"sys_pk":6,"parent":5,"codigo":"B1","nombre":"Subgrupo B1","importe":7},{"sys_pk":7,"parent":null,"codigo":"C","nombre":"Grupo C","importe":0}];
                const pages = {};

                if (table)
                {
                    table.AutoAddRow = false;
                    table.AutoDelRow = false;
                    table.EverMove = false;

                    // Vista con filas anidadas
                    if (true)
                    {
                        table.removeAttribute("data");
                        table.DataArray = data;
                        table._expandOnStart = false;
                        table._printTreeData();
                    }
                    // Paginación
                    if (false)
                    {
                        let perPage = 250
                        let numItems = data.length
                        let numPages = Math.ceil(numItems / perPage)
                        let currentPage = 1

                        for (let i = 0; i < numItems; i += perPage) {
                            pages[Object.keys(pages).length + 1] = data.slice(i, i + perPage)
                        }

                        const renderPagination = () =>
                        {
                            const container = document.getElementById("tbl_arbol_pagination")

                            if (!container || numPages <= 1) return

                            let html = ""

                            html += `
                                <button type="button"
                                    class="btn btn-sm btn-outline-secondary"
                                    ${currentPage === 1 ? "disabled" : ""}
                                    onclick="pagination.goto(${currentPage - 1})">
                                    &lt;
                                </button>
                            `

                            if (numPages <= 5)
                            {
                                for (let page = 1; page <= numPages; page++)
                                {
                                    html += `
                                        <button type="button"
                                            class="btn btn-sm ${page === currentPage ? "btn-secondary" : "btn-outline-secondary"}"
                                            onclick="pagination.goto(${page})">
                                            ${page}
                                        </button>
                                    `
                                }
                            }
                            else
                            {
                                html += `
                                    <button type="button"
                                        class="btn btn-sm ${currentPage === 1 ? "btn-secondary" : "btn-outline-secondary"}"
                                        onclick="pagination.goto(1)">
                                        1
                                    </button>
                                `

                                if (currentPage > 3)
                                    html += `<span class="px-1">...</span>`

                                let start = Math.max(2, currentPage - 1)
                                let end = Math.min(numPages - 1, currentPage + 1)

                                if (currentPage <= 3)
                                {
                                    start = 2
                                    end = 3
                                }

                                if (currentPage >= numPages - 2)
                                {
                                    start = numPages - 2
                                    end = numPages - 1
                                }

                                for (let page = start; page <= end; page++)
                                {
                                    html += `
                                        <button type="button"
                                            class="btn btn-sm ${page === currentPage ? "btn-secondary" : "btn-outline-secondary"}"
                                            onclick="pagination.goto(${page})">
                                            ${page}
                                        </button>
                                    `
                                }

                                if (currentPage < numPages - 2)
                                    html += `<span class="px-1">...</span>`

                                html += `
                                    <button type="button"
                                        class="btn btn-sm ${currentPage === numPages ? "btn-secondary" : "btn-outline-secondary"}"
                                        onclick="pagination.goto(${numPages})">
                                        Último
                                    </button>
                                `
                            }

                            html += `
                                <button type="button"
                                    class="btn btn-sm btn-outline-secondary"
                                    ${currentPage === numPages ? "disabled" : ""}
                                    onclick="pagination.goto(${currentPage + 1})">
                                    &gt;
                                </button>
                            `

                            container.innerHTML = html
                        }

                        window.pagination = {
                            goto: (numPage) =>
                            {
                                if (numPage < 1 || numPage > numPages) return

                                const leyend = document.getElementById("tbl_arbol_leyend")
                                currentPage = numPage

                                table.DataArray = pages[numPage] ?? []
                                if (leyend)
                                {
                                    let start = (numPage - 1) * perPage
                                    let end = start + table.DataArray.length
                                    let text = "Mostrando registros: " + start +" a "+ end +" de "+ numItems
                                    leyend.textContent = text
                                }
                                table._printRows()

                                renderPagination()
                            }
                        }

                        table.removeAttribute("data")
                        pagination.goto(1)
                    }

                    table.Events[table.EdiTable.Const.Events.OnSort] = (e) =>
                    {
                        const table_leyend = document.getElementById("tbl_arbol_leyend");
                        let length = (table?.DataArray ?? []).length;
                        let leyend = "No se encontraron resultados.";

                        if (length > 0) leyend = "Mostrando los primeros "+length+" registros";
                        if (e && length > 0) leyend += " ordenados por "+e.caption+" "+e.coldef.sort;

                        table_leyend.textContent = leyend;
                    }
                }
            });"

